def temperature_json(temperature, sensor="OK", sensor_id="", calibrated=False,
                    raw_temperature=None):
    """Serialize identical MQTT and HTTP temperature data with calibration metadata."""
    if raw_temperature is None and temperature is not None and not calibrated:
        raw_temperature = temperature
    return json.dumps({
        "temperature": temperature,
        "unit": "\u00b0C",
        "sensor": sensor,
        "sensor_id": sensor_id,
        "calibrated": bool(calibrated),
        "raw_temperature": raw_temperature,
    })


def status_json(values):
    """Serialize the shared temperature payload for the live status poll."""
    sensor = values.get("sensor", "OK" if values["temperature"] is not None else "Sensor error")
    return temperature_json(
        values["temperature"], sensor, values.get("sensor_id", ""),
        values.get("calibration_applied", False),
        values.get("raw_temperature", values["temperature"]))


def temperature_api_json(values):
    """Serialize the same complete payload used by MQTT and status polling."""
    return status_json(values)


def ipv4(value):
    """Validate dotted IPv4 notation and return its integer representation."""
    parts = value.split(".")
    if len(parts) != 4:
        raise ValueError("Invalid IPv4 address: " + value)
    result = 0
    for part in parts:
        if not part or not all("0" <= char <= "9" for char in part):
            raise ValueError("Invalid IPv4 address: " + value)
        number = int(part)
        if number > 255 or (len(part) > 1 and part[0] == "0"):
            raise ValueError("Invalid IPv4 address: " + value)
        result = (result << 8) | number
    return result


def validate_config(values):
    """Validate all settings before allowing any persistent change."""
    if not isinstance(values, dict) or set(values) != set(DEFAULT_CONFIG):
        raise ValueError("Settings are incomplete or contain unknown fields.")
    checked = values.copy()
    checked["calibration"] = validate_calibration(checked["calibration"])
    if type(checked["dhcp"]) is not bool:
        raise ValueError("Invalid DHCP mode.")
    if type(checked["mqtt_enabled"]) is not bool:
        raise ValueError("Invalid MQTT mode.")
    for name in ("mqtt_port", "interval"):
        if type(checked[name]) is not int or not 1 <= checked[name] <= 65535:
            raise ValueError(name + " must be between 1 and 65535.")
    for name, limit in (("ip", 15), ("netmask", 15), ("gateway", 15),
                        ("dns", 15), ("mqtt_server", 253), ("mqtt_topic", 256),
                        ("mqtt_user", 128), ("mqtt_password", 256)):
        value = checked[name]
        if not isinstance(value, str) or len(value.encode("utf-8")) > limit:
            raise ValueError("Invalid or oversized value: " + name)
        if any(ord(char) < 32 or ord(char) == 127 for char in value):
            raise ValueError("Control characters are not allowed: " + name)
    host = checked["mqtt_server"]
    if host and (not all(char.isalpha() or char.isdigit() or char in ".-" for char in host)
                 or not all(ord(char) < 128 for char in host)):
        raise ValueError("MQTT broker must be an IPv4 address or DNS name without a port.")
    if not checked["mqtt_topic"] or any(char in checked["mqtt_topic"] for char in "+#"):
        raise ValueError("MQTT topic cannot be empty or contain wildcards.")
    if not checked["dhcp"]:
        address = ipv4(checked["ip"])
        mask = ipv4(checked["netmask"])
        gateway = ipv4(checked["gateway"])
        ipv4(checked["dns"])
        inverse = mask ^ 0xffffffff
        if not mask or inverse < 3 or inverse & (inverse + 1):
            raise ValueError("Subnet mask must be contiguous (/1 to /30).")
        if address >> 24 in (0, 127) or address >> 24 >= 224:
            raise ValueError("No usable local IPv4 address.")
        if address & inverse in (0, inverse):
            raise ValueError("IP address cannot be the network or broadcast address.")
        if gateway and ((gateway & mask) != (address & mask)
                        or gateway & inverse in (0, inverse) or gateway == address):
            raise ValueError("Gateway must be another host address on the same subnet.")
    return checked


def write_json_atomic(path, values):
    """Replace one JSON file only after a complete temporary-file write."""
    temporary = path + ".tmp"
    try:
        with open(temporary, "w") as stream:
            json.dump(values, stream)
            stream.flush()
        replace = getattr(os, "replace", None)
        if replace is None:
            os.rename(temporary, path)
        else:
            replace(temporary, path)
    except OSError:
        try:
            os.remove(temporary)
        except OSError:
            pass
        raise


def load_calibration(embedded=DEFAULT_CALIBRATION):
    """Load calibration.json, migrating embedded legacy profiles if necessary."""
    try:
        with open(CALIBRATION_FILE) as stream:
            return validate_calibration(json.load(stream))
    except OSError:
        checked = validate_calibration(embedded)
        try:
            write_json_atomic(CALIBRATION_FILE, checked)
        except OSError:
            print("Could not create calibration.json; using available profile data.")
        return checked
    except (ValueError, TypeError):
        print("Invalid calibration.json; calibration is disabled.")
        return DEFAULT_CALIBRATION.copy()


def load_config():
    """Load settings, falling back to DHCP when the file is absent or invalid."""
    try:
        with open(CONFIG_FILE) as stream:
            values = json.load(stream)
        embedded_calibration = DEFAULT_CALIBRATION
        if isinstance(values, dict) and set(values) in (
                {"ip", "mqtt"}, {"ip", "mqtt", "calibration"}):
            ip_values = values["ip"]
            mqtt_values = values["mqtt"]
            embedded_calibration = values.get("calibration", DEFAULT_CALIBRATION)
            if (not isinstance(ip_values, dict)
                    or set(ip_values) != {"dhcp", "address", "netmask", "gateway", "dns"}
                    or not isinstance(mqtt_values, dict)
                    or set(mqtt_values) != {"enabled", "server", "port", "topic", "user", "password", "interval"}):
                raise ValueError("Invalid grouped configuration.")
            values = {
                "dhcp": ip_values["dhcp"],
                "ip": ip_values["address"],
                "netmask": ip_values["netmask"],
                "gateway": ip_values["gateway"],
                "dns": ip_values["dns"],
                "mqtt_enabled": mqtt_values["enabled"],
                "mqtt_server": mqtt_values["server"],
                "mqtt_port": mqtt_values["port"],
                "mqtt_topic": mqtt_values["topic"],
                "mqtt_user": mqtt_values["user"],
                "mqtt_password": mqtt_values["password"],
                "interval": mqtt_values["interval"],
            }
        elif isinstance(values, dict):
            embedded_calibration = values.pop("calibration", DEFAULT_CALIBRATION)
            if set(values) == set(DEFAULT_CONFIG) - {"calibration"}:
                pass
            elif set(values) == set(DEFAULT_CONFIG) - {"mqtt_enabled", "calibration"}:
                values["mqtt_enabled"] = bool(values["mqtt_server"])
            else:
                raise ValueError("Invalid flat configuration.")
        values["calibration"] = load_calibration(embedded_calibration)
        return validate_config(values)
    except (OSError, ValueError, TypeError):
        print("No valid config.json; starting with DHCP and MQTT disabled.")
        return DEFAULT_CONFIG.copy()


def save_config(values):
    """Replace the configuration only after a complete temporary-file write."""
    checked = validate_config(values)
    stored = {
        "ip": {
            "dhcp": checked["dhcp"],
            "address": checked["ip"],
            "netmask": checked["netmask"],
            "gateway": checked["gateway"],
            "dns": checked["dns"],
        },
        "mqtt": {
            "enabled": checked["mqtt_enabled"],
            "server": checked["mqtt_server"],
            "port": checked["mqtt_port"],
            "topic": checked["mqtt_topic"],
            "user": checked["mqtt_user"],
            "password": checked["mqtt_password"],
            "interval": checked["interval"],
        },
    }
    write_json_atomic(CONFIG_FILE, stored)
    write_json_atomic(CALIBRATION_FILE, checked["calibration"])


def decode_form(body):
    """Decode bounded URL-encoded UTF-8 form data, rejecting duplicate fields."""
    result = {}
    for pair in body.split(b"&"):
        if b"=" not in pair:
            raise ValueError("Invalid form data.")
        decoded = []
        for part in pair.split(b"=", 1):
            part = part.replace(b"+", b" ")
            buffer = bytearray()
            index = 0
            while index < len(part):
                if part[index] == 37:
                    if index + 2 >= len(part):
                        raise ValueError("Invalid URL encoding.")
                    digits = part[index + 1:index + 3]
                    if any(char not in b"0123456789abcdefABCDEF" for char in digits):
                        raise ValueError("Invalid URL encoding.")
                    buffer.append(int(digits, 16))
                    index += 3
                else:
                    buffer.append(part[index])
                    index += 1
            decoded.append(buffer.decode("utf-8"))
        name, value = decoded
        if name in result:
            raise ValueError("Duplicate form field.")
        result[name] = value
    return result


def calibration_from_form(fields, previous):
    """Update one profile while retaining all other saved profiles."""
    calibration = validate_calibration(previous)
    existing_id = fields["calibration_profile"].strip()
    new_id = fields["calibration_new_id"].strip()
    if existing_id and new_id:
        raise ValueError("Select an existing profile or enter a new profile ID, not both.")
    profile_id = existing_id or new_id
    profiles = calibration["profiles"]
    if not profile_id:
        return {"active_id": "", "profiles": profiles}
    try:
        count = int(fields["calibration_count"])
    except ValueError:
        raise ValueError("Calibration point count must be between 2 and 10.")
    if not 2 <= count <= 10:
        raise ValueError("Calibration point count must be between 2 and 10.")
    points = []
    for index in range(1, count + 1):
        try:
            measured = float(fields["calibration_measured_" + str(index)])
            reference = float(fields["calibration_reference_" + str(index)])
        except ValueError:
            raise ValueError("Enter both temperatures for every calibration point.")
        points.append({"measured": measured, "reference": reference})
    profiles[profile_id] = {"points": points}
    return validate_calibration({"active_id": profile_id, "profiles": profiles})


def form_config(fields, previous):
    """Convert a full form without ever returning the stored MQTT password."""
    point_fields = {
        "calibration_" + kind + "_" + str(index)
        for kind in ("measured", "reference") for index in range(1, 11)
    }
    required = set(DEFAULT_CONFIG) - {"mqtt_password", "calibration"}
    required |= {"mqtt_password", "csrf", "clear_password", "calibration_profile",
                 "calibration_new_id", "calibration_count"}
    required |= point_fields
    if set(fields) != required:
        raise ValueError("Incomplete form.")
    values = {name: fields[name].strip() for name in DEFAULT_CONFIG if name != "calibration"}
    if values["dhcp"] not in ("yes", "no"):
        raise ValueError("Invalid DHCP mode.")
    values["dhcp"] = values["dhcp"] == "yes"
    if values["mqtt_enabled"] not in ("yes", "no"):
        raise ValueError("Invalid MQTT mode.")
    values["mqtt_enabled"] = values["mqtt_enabled"] == "yes"
    for name in ("mqtt_port", "interval"):
        values[name] = int(values[name])
    values["mqtt_password"] = fields["mqtt_password"] or previous["mqtt_password"]
    if fields["clear_password"] == "yes":
        values["mqtt_password"] = ""
    values["calibration"] = calibration_from_form(
        fields, previous.get("calibration", DEFAULT_CALIBRATION))
    return validate_config(values)


def escape_html(value):
    """Escape values inserted into HTML text and quoted attributes."""
    return str(value).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;").replace("'", "&#39;")


