class ConfigServer:
    """Serve LAN settings without a login while protecting form submissions."""

    def __init__(self, config, status, restart):
        """Create a CSRF token without a web password or exposing MQTT secrets."""
        self.config = config
        self.status = status
        self.restart = restart
        self.csrf = binascii.hexlify(os.urandom(16)).decode()
        self.page_nonce = binascii.hexlify(os.urandom(16)).decode()
        self.busy = False
        self.restart_pending = False

    def page(self, message=""):
        """Render an accessible form with escaped configuration and status values."""
        self.page_nonce = binascii.hexlify(os.urandom(16)).decode()
        values = self.status()
        mqtt_status = values["mqtt"]
        mqtt_enabled = values.get("mqtt_enabled", mqtt_status != "Disabled")
        calibration = self.config.get("calibration", DEFAULT_CALIBRATION)
        calibration_id = calibration["active_id"]
        points = calibration["profiles"].get(calibration_id, {}).get("points", [])
        calibration_count = len(points) or 2
        replacements = {
            "status_class": "status with-mqtt" if mqtt_enabled else "status",
            "address": values["ip"],
            "mac": values.get("mac", "--"),
            "temperature": str(values["temperature"]) + " \u00b0C" if values["temperature"] is not None else "--",
            "sensor_id": values.get("sensor_id") or "--",
            "calibration_visibility": "" if values.get("calibration_applied", False) else "hidden",
            "sensor": values.get("sensor", "OK" if values["temperature"] is not None else "Sensor error"),
            "csrf": self.csrf,
            "page_nonce": self.page_nonce,
            "calibration_id": calibration_id,
            "calibration_count": str(calibration_count),
            "calibration_new_hidden": "hidden" if calibration_id else "",
        }
        page = PAGE
        for name, value in replacements.items():
            page = page.replace("@" + name + "@", escape_html(value))
        calibration_options = ['<option value="">Create new profile...</option>']
        for profile_id in sorted(calibration["profiles"]):
            selected = " selected" if profile_id == calibration_id else ""
            escaped_id = escape_html(profile_id)
            calibration_options.append(
                '<option value="' + escaped_id + '"' + selected + '>'
                + escaped_id + '</option>')
        page = page.replace("@calibration_options@", "".join(calibration_options))
        page = page.replace("@calibration_profiles@", json.dumps(calibration["profiles"]))
        calibration_fields = []
        for index in range(1, 11):
            point = points[index - 1] if index <= len(points) else {}
            hidden = " hidden" if not calibration_id or index > calibration_count else ""
            required = " required" if calibration_id and index <= calibration_count else ""
            calibration_fields.append(
                '<div class="calibration-point" data-index="' + str(index) + '"' + hidden + '>'
                + '<strong>Point ' + str(index) + '</strong>'
                + '<label>Sensor reading (\u00b0C)<input type="number" step="any" name="calibration_measured_'
                + str(index) + '" value="' + escape_html(point.get("measured", "")) + '"' + required + '></label>'
                + '<label>Reference temperature (\u00b0C)<input type="number" step="any" name="calibration_reference_'
                + str(index) + '" value="' + escape_html(point.get("reference", "")) + '"' + required + '></label>'
                + '</div>')
        page = page.replace("@calibration_fields@", "".join(calibration_fields))
        mqtt_reading = ('<div class="reading"><span>MQTT status</span><strong>'
                        + escape_html(mqtt_status) + "</strong></div>" if mqtt_enabled else "")
        page = page.replace("@mqtt_reading@", mqtt_reading)
        for group, items in (
            ("network", (("ip", "IP address"), ("netmask", "Subnet mask"),
                         ("gateway", "Gateway"), ("dns", "DNS server"))),
            ("mqtt", (("mqtt_server", "Broker (blank = disabled)"), ("mqtt_port", "Port"),
                      ("mqtt_topic", "Topic"), ("mqtt_user", "Username"),
                      ("interval", "Publish interval (seconds)"))),
        ):
            inputs = []
            for name, label in items:
                numeric = name in ("mqtt_port", "interval")
                attributes = 'type="number" min="1" max="65535"' if numeric else 'type="text" maxlength="256"'
                inputs.append('<label>' + label + '<input name="' + name + '" ' + attributes
                              + ' value="' + escape_html(self.config[name]) + '"></label>')
            page = page.replace("@" + group + "_fields@", "".join(inputs))
        page = page.replace("@dhcp_yes@", "checked" if self.config["dhcp"] else "")
        page = page.replace("@dhcp_no@", "" if self.config["dhcp"] else "checked")
        mqtt_enabled = self.config.get("mqtt_enabled", bool(self.config.get("mqtt_server")))
        page = page.replace("@mqtt_off@", "" if mqtt_enabled else "checked")
        page = page.replace("@mqtt_on@", "checked" if mqtt_enabled else "")
        return page.replace("@message@", '<p class="message" role="status">' + escape_html(message) + "</p>" if message else "")

    async def respond(self, writer, status, body, content_type="text/html; charset=utf-8", extra=""):
        """Send a length-delimited response with no caching or external resources."""
        payload = body.encode("utf-8")
        header = ("HTTP/1.1 " + status + "\r\nContent-Type: " + content_type
                  + "\r\nContent-Length: " + str(len(payload))
                  + "\r\nConnection: close\r\nCache-Control: no-store"
                  + "\r\nX-Content-Type-Options: nosniff\r\nX-Frame-Options: DENY"
                  + "\r\nReferrer-Policy: no-referrer"
              + "\r\nContent-Security-Policy: default-src 'none'; connect-src 'self'; style-src 'unsafe-inline'; script-src 'nonce-"
              + self.page_nonce + "'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'\r\n"
                  + extra + "\r\n")
        writer.write(header.encode() + payload)
        await writer.drain()

    async def read_request(self, reader):
        """Read at most 4 KiB headers and 4 KiB body, including fragmented TCP data."""
        header = bytearray()
        while not header.endswith(b"\r\n\r\n"):
            chunk = await reader.read(1)
            if not chunk or len(header) >= 4096:
                raise ValueError("HTTP header is missing or too large.")
            header.extend(chunk)
        lines = header.decode("utf-8").split("\r\n")
        method, path, version = lines[0].split(" ")
        if version not in ("HTTP/1.0", "HTTP/1.1"):
            raise ValueError("Invalid HTTP version.")
        headers = {}
        for line in lines[1:-2]:
            name, value = line.split(":", 1)
            name = name.lower().strip()
            if name in headers:
                raise ValueError("Duplicate HTTP header.")
            headers[name] = value.strip()
        if "transfer-encoding" in headers:
            raise ValueError("Transfer-Encoding is not supported.")
        length = int(headers.get("content-length", "0"))
        if not 0 <= length <= 4096:
            raise ValueError("Form is too large.")
        body = bytearray()
        while len(body) < length:
            chunk = await reader.read(length - len(body))
            if not chunk:
                raise ValueError("Incomplete form.")
            body.extend(chunk)
        return method, path, headers, bytes(body)

    async def dispatch(self, reader, writer):
        """Allow LAN access; only CSRF-protected POST can change settings."""
        method, path, headers, body = await self.read_request(reader)
        if method == "GET" and path == "/":
            await self.respond(writer, "200 OK", self.page())
        elif method == "GET" and path == "/api/calibration":
            calibration = validate_calibration(
                self.config.get("calibration", DEFAULT_CALIBRATION))
            await self.respond(writer, "200 OK", json.dumps(calibration),
                               "application/json; charset=utf-8")
        elif method == "POST" and path == "/api/calibration":
            if headers.get("content-type", "").split(";", 1)[0].strip() != "application/json":
                await self.respond(writer, "415 Unsupported Media Type",
                                   json.dumps({"error": "Expected application/json."}),
                                   "application/json; charset=utf-8")
                return
            try:
                fields = json.loads(body.decode("utf-8"))
                if (not isinstance(fields, dict)
                        or set(fields) not in ({"sensor_id"}, {"sensor_id", "points"})):
                    raise ValueError("Expected sensor_id and optional points.")
                calibration = update_calibration(
                    self.config.get("calibration", DEFAULT_CALIBRATION),
                    fields["sensor_id"], fields.get("points"))
            except (ValueError, TypeError) as error:
                await self.respond(writer, "400 Bad Request", json.dumps({"error": str(error)}),
                                   "application/json; charset=utf-8")
                return
            updated = dict(self.config, calibration=calibration)
            save_config(updated)
            self.config["calibration"] = calibration
            await self.respond(writer, "200 OK", json.dumps(calibration),
                               "application/json; charset=utf-8")
        elif method == "GET" and path == "/api/status":
            await self.respond(writer, "200 OK", status_json(self.status()), "application/json; charset=utf-8")
        elif method == "GET" and path == "/api/temperature":
            values = self.status()
            await self.respond(writer, "200 OK", temperature_api_json(values),
                               "application/json; charset=utf-8")
        elif method == "POST" and path == "/save":
            if self.restart_pending:
                await self.respond(writer, "409 Conflict", "Reboot is already scheduled.")
                return
            if headers.get("content-type", "").split(";", 1)[0].strip() != "application/x-www-form-urlencoded":
                raise ValueError("Invalid form content type.")
            fields = decode_form(body)
            if fields.get("csrf") != self.csrf:
                await self.respond(writer, "403 Forbidden",
                                   self.page("Form token expired. Please submit again."))
                return
            try:
                values = form_config(fields, self.config)
            except ValueError as error:
                await self.respond(writer, "400 Bad Request", self.page(str(error)))
                return
            save_config(values)
            self.restart_pending = True
            self.restart()
            await self.respond(writer, "200 OK", self.page("Saved. Rebooting in a few seconds. The IP address may change."))
        else:
            await self.respond(writer, "404 Not Found", "Not found.")

    async def handle(self, reader, writer):
        """Limit concurrent work, request duration and always close client streams."""
        acquired = not self.busy
        try:
            if not acquired:
                return
            self.busy = True
            try:
                await asyncio.wait_for(self.dispatch(reader, writer), 5)
            except (ValueError, UnicodeError):
                await asyncio.wait_for(self.respond(writer, "400 Bad Request", "Invalid HTTP request."), 2)
            except OSError:
                await asyncio.wait_for(self.respond(writer, "503 Service Unavailable", "Request or save failed. Please try again."), 2)
            except asyncio.TimeoutError:
                pass
        except (OSError, asyncio.TimeoutError):
            pass
        finally:
            if acquired:
                self.busy = False
            writer.close()
            try:
                await writer.wait_closed()
            except OSError:
                pass